contract InvMutTest
{
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function test(LogFile _log, uint256 amt) public
    { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amt)); require(amt <= 1000000000000000000000000000000);
        require(amt > 0);
        c.SetLogFile(address(_log)); if (__ESBMC_reverted()) return;
        c.Deposit{value: amt}(); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == amt);
    }
}
